-- The `UUID2` values in the parameters of aggregate functions keep the identifier,
-- both for a direct call and for an aggregate function created from a string.

SELECT sumMapFiltered([toUUID2('00000000-0000-0000-0000-000000000001')])([toUUID2('00000000-0000-0000-0000-000000000001')], [7]);
SELECT sumMapFilteredWithOverflow([toUUID2('00000000-0000-0000-0000-000000000001')])([toUUID2('00000000-0000-0000-0000-000000000001')], [toUInt8(7)]);
SELECT sumMapFiltered([toUUID2('00000000-0000-0000-0000-000000000002')])([toUUID2('00000000-0000-0000-0000-000000000001')], [7]);
SELECT sumMapFiltered([toUUID('00000000-0000-0000-0000-000000000001')])([toUUID2('00000000-0000-0000-0000-000000000001')], [7]);
SELECT sumMapFiltered([toUUID2('00000000-0000-0000-0000-000000000001')])([toUUID('00000000-0000-0000-0000-000000000001')], [7]);
SELECT sumMapFiltered([(toUUID2('00000000-0000-0000-0000-000000000001'), 1)])([(toUUID2('00000000-0000-0000-0000-000000000001'), 1)], [7]);

SELECT initializeAggregation('groupArrayInsertAt(toUUID2(\'00000000-0000-0000-0000-000000000001\'), 2)', toUUID2('00000000-0000-0000-0000-000000000001'), toUInt64(1));
SELECT groupArrayInsertAt(toUUID2('00000000-0000-0000-0000-000000000001'), 2)(toUUID2('00000000-0000-0000-0000-000000000001'), toUInt64(1));
SELECT finalizeAggregation(initializeAggregation('sumMapFilteredState([toUUID2(\'00000000-0000-0000-0000-000000000001\')])', [toUUID2('00000000-0000-0000-0000-000000000001')], [7]));

-- The old analyzer takes the parameters from the AST.
SELECT sumMapFiltered([toUUID2('00000000-0000-0000-0000-000000000001')])([toUUID2('00000000-0000-0000-0000-000000000001')], [7]) SETTINGS enable_analyzer = 0;
SELECT groupArrayInsertAt(toUUID2('00000000-0000-0000-0000-000000000001'), 2)(toUUID2('00000000-0000-0000-0000-000000000001'), toUInt64(1)) SETTINGS enable_analyzer = 0;
